  BlockStable o b → LeafValid l → ∀ (A B : Full a b), hybridEval o l A B = A * B ∧ scheduledGateCount o l = r * ell
@hybrid_W_cost : ∀ {K : Type u_2} [inst : CommRing K] {a b r : ℕ} (o : Outer K a r) (l : Leaf K b (W b)),
  BlockStable o b → LeafValid l → ∀ (A B : Full a b), hybridEval o l A B = A * B ∧ scheduledGateCount o l = r * W b
